     1→"use client";
     2→
     3→import type { Question, Survey } from "@orksys-survey/db";
     4→import { createContext, useContext } from "react";
     5→
     6→import type { SurveyBuilderContextValue } from "./types";
     7→
     8→const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(
     9→	null,
    10→);
    11→
    12→export interface SurveyBuilderProviderProps {
    13→	survey: Survey;
    14→	questions: Question[];
    15→	selectedQuestionId: string | null;
    16→	setSelectedQuestionId: (id: string | null) => void;
    17→	activeTab: "build" | "preview" | "share";
    18→	setActiveTab: (tab: "build" | "preview" | "share") => void;
    19→	onQuestionsChange: (questions: Question[]) => void;
    20→	paletteOpen: boolean;
    21→	setPaletteOpen: (open: boolean) => void;
    22→	propertiesOpen: boolean;
    23→	setPropertiesOpen: (open: boolean) => void;
    24→	settingsOpen: boolean;
    25→	setSettingsOpen: (open: boolean) => void;
    26→	children: React.ReactNode;
    27→}
    28→
    29→export function SurveyBuilderProvider({
    30→	survey,
    31→	questions,
    32→	selectedQuestionId,
    33→	setSelectedQuestionId,
    34→	activeTab,
    35→	setActiveTab,
    36→	onQuestionsChange,
    37→	paletteOpen,
    38→	setPaletteOpen,
    39→	propertiesOpen,
    40→	setPropertiesOpen,
    41→	settingsOpen,
    42→	setSettingsOpen,
    43→	children,
    44→}: SurveyBuilderProviderProps) {
    45→	const contextValue: SurveyBuilderContextValue = {
    46→		survey,
    47→		questions,
    48→		selectedQuestionId,
    49→		setSelectedQuestionId,
    50→		activeTab,
    51→		setActiveTab,
    52→		onQuestionsChange,
    53→		paletteOpen,
    54→		setPaletteOpen,
    55→		propertiesOpen,
    56→		setPropertiesOpen,
    57→		settingsOpen,
    58→		setSettingsOpen,
    59→	};
    60→
    61→	return (
    62→		<SurveyBuilderContext.Provider value={contextValue}>
    63→			{children}
    64→		</SurveyBuilderContext.Provider>
    65→	);
    66→}
    67→
    68→export function useSurveyBuilder() {
    69→	const context = useContext(SurveyBuilderContext);
    70→	if (!context) {
    71→		throw new Error(
    72→			"useSurveyBuilder must be used within a SurveyBuilder component",
    73→		);
    74→	}
    75→	return context;
    76→}
