    19→
    20→// Re-export types
    21→export type { QuestionCardContentProps };
    22→export type { questionTypeIcons, questionTypeLabels };
    23→
    24→// Compound component types
    25→export interface QuestionCardBadgeProps {
    26→	children: React.ReactNode;
    27→	className?: string;
    28→}
    29→
    30→export interface QuestionCardActionsProps {
    31→	onDelete?: () => void;
    32→	isDeleting?: boolean;
    33→	className?: string;
    34→}
    35→
    36→// Context for sharing question card state with compound components
    37→interface QuestionCardContextValue {
    38→	question: Question;
    39→	isOverlay?: boolean;
    40→	isSelected?: boolean;
    41→}
    42→
    43→const QuestionCardContext = createContext<QuestionCardContextValue | null>(
    44→	null,
    45→);
    46→
    47→function useQuestionCardContext() {
    48→	const context = useContext(QuestionCardContext);
    49→	if (!context) {
    50→		throw new Error(
    51→			"QuestionCard compound components must be used within QuestionCard",
    52→		);
    53→	}
    54→	return context;
    55→}
    56→
    57→interface QuestionCardProps {
    58→	question: Question;
    59→	isSelected: boolean;
    60→	onSelect: () => void;
    61→	questions: Question[];
    62→	onQuestionsChange: (questions: Question[]) => void;
    63→	children?: React.ReactNode;
    64→}
    65→
    66→const animateLayoutChanges: AnimateLayoutChanges = () => {
    67→	return false;
    68→};
    69→
    70→export const QuestionCard = memo(function QuestionCard({
    71→	question,
    72→	isSelected,
    73→	onSelect,
    74→	questions,
    75→	onQuestionsChange,
    76→	children,
    77→}: QuestionCardProps) {
    78→	const queryClient = useQueryClient();
    79→
    80→	// Sortable for reordering within canvas
    81→	const {
    82→		attributes,
    83→		listeners,
    84→		setNodeRef: setSortableRef,
    85→		transform,
    86→		transition,
    87→		isDragging,
    88→	} = useSortable({
    89→		id: question.id,
    90→		animateLayoutChanges,
    91→	});
    92→
    93→	// Droppable for palette item drops
    94→	const { setNodeRef: setDroppableRef, isOver } = useDroppable({
    95→		id: question.id,
    96→	});
    97→
    98→	// Combine refs so element is both sortable and droppable
    99→	const setNodeRef = (node: HTMLElement | null) => {
   100→		setSortableRef(node);
   101→		setDroppableRef(node);
   102→	};
   103→
   104→	const deleteMutation = useMutation(
   105→		orpc.question.delete.mutationOptions({
   106→			onSuccess: () => {
   107→				onQuestionsChange(questions.filter((q) => q.id !== question.id));
   108→				queryClient.invalidateQueries({ queryKey: ["question"] });
   109→				toast.success("Question deleted");
   110→			},
   111→			onError: (error) => {
   112→				toast.error(error.message || "Failed to delete question");
   113→			},
   114→		}),
   115→	);
   116→
   117→	// Query logic rules to check if this question has any
   118→	const logicRules = useQuery(
   119→		orpc.logicRule.list.queryOptions({
   120→			input: { surveyId: question.surveyId },
   121→		}),
   122→	);
   123→
   124→	const hasLogic = logicRules.data?.some(
   125→		(rule) => rule.sourceQuestionId === question.id,
   126→	);
   127→
   128→	const style = {
   129→		transform: CSS.Translate.toString(transform),
   130→		transition,
   131→		zIndex: isDragging ? 50 : undefined,
   132→	};
   133→
   134→	const contextValue: QuestionCardContextValue = {
   135→		question,
   136→		isOverlay: false,
   137→		isSelected,
   138→	};
   139→
   140→	return (
   141→		<QuestionCardContext.Provider value={contextValue}>
   142→			<motion.div
   143→				ref={setNodeRef}
   144→				style={style}
   145→				className={cn(isDragging && "z-50")}
   146→			>
   147→				<QuestionCardContent
   148→					question={question}
   149→					isSelected={isSelected}
   150→					hasLogic={hasLogic}
   151→					onSelect={onSelect}
   152→					dragHandleProps={{ ...attributes, ...listeners }}
   153→					isDragging={isDragging}
   154→					isOver={isOver}
   155→				>
   156→					<QuestionCardActions
   157→						onDelete={() => deleteMutation.mutate({ id: question.id })}
   158→						isDeleting={deleteMutation.isPending}
   159→					/>
   160→				</QuestionCardContent>
   161→			</motion.div>
   162→		</QuestionCardContext.Provider>
   163→	);
   164→});
   165→
   166→// Badge component for displaying question metadata
   167→export const QuestionCardBadge = function QuestionCardBadge({
   168→	children,
   169→	className,
   170→}: QuestionCardBadgeProps) {
   171→	const { question } = useQuestionCardContext();
   172→	return (
   173→		<motion.span
   174→			initial={{ opacity: 0, scale: 0.8 }}
   175→			animate={{ opacity: 1, scale: 1 }}
   176→			className={cn(
   177→				"flex items-center gap-1 rounded bg-violet-100 px-1.5 py-0.5 font-medium text-[10px] text-violet-600",
   178→				className,
   179→			)}
   180→		>
   181→			{children}
   182→		</motion.span>
   183→	);
   184→};
   185→
   186→// Actions component for question card actions (delete, etc.)
   187→export const QuestionCardActions = function QuestionCardActions({
   188→	onDelete,
   189→	isDeleting = false,
   190→	className,
   191→}: QuestionCardActionsProps) {
   192→	const { question, isSelected, isOverlay } = useQuestionCardContext();
   193→
   194→	if (isOverlay || !onDelete) {
   195→		return null;
   196→	}
   197→
   198→	return (
   199→		<DeleteConfirmButton
   200→			onDelete={onDelete}
   201→			isDeleting={isDeleting}
   202→			className={cn(
   203→				"opacity-0 transition-opacity group-hover:opacity-100 data-[selected=true]:opacity-100",
   204→				className,
   205→			)}
   206→			data-selected={isSelected}
   207→		/>
   208→	);
   209→};
