    22→export function QuestionRenderer({ question }: QuestionRendererProps) {
    23→	const { answers, setAnswer, currentError } = useSurveyRunner();
    24→	const value = answers.get(question.id);
    25→	const error = currentError;
    26→
    27→	const handleChange = (newValue: unknown) => {
    28→		setAnswer(question.id, newValue);
    29→	};
    30→
    31→	switch (question.type) {
    32→		case "text":
    33→			return (
    34→				<TextQuestion
    35→					question={question}
    36→					value={value as string | undefined}
    37→					onChange={(v) => handleChange(v)}
    38→					error={error}
    39→				/>
    40→			);
    41→		case "textarea":
    42→			return (
    43→				<TextareaQuestion
    44→					question={question}
    45→					value={value as string | undefined}
    46→					onChange={(v) => handleChange(v)}
    47→					error={error}
    48→				/>
    49→			);
    50→		case "multiple_choice":
    51→			return (
    52→				<ChoiceQuestion
    53→					question={question}
    54→					value={value as string | undefined}
    55→					onChange={(v) => handleChange(v)}
    56→					error={error}
    57→				/>
    58→			);
    59→		case "checkbox":
    60→			return (
    61→				<CheckboxQuestion
    62→					question={question}
    63→					value={value as string[] | undefined}
    64→					onChange={(v) => handleChange(v)}
    65→					error={error}
    66→				/>
    67→			);
    68→		case "dropdown":
    69→			return (
    70→				<DropdownQuestion
    71→					question={question}
    72→					value={value as string | undefined}
    73→					onChange={(v) => handleChange(v)}
    74→					error={error}
    75→				/>
    76→			);
    77→		case "rating":
    78→			return (
    79→				<RatingQuestion
    80→					question={question}
    81→					value={value as number | undefined}
    82→					onChange={(v) => handleChange(v)}
    83→					error={error}
    84→				/>
    85→			);
    86→		case "nps":
    87→			return (
    88→				<NpsQuestion
    89→					question={question}
    90→					value={value as number | undefined}
    91→					onChange={(v) => handleChange(v)}
    92→					error={error}
    93→				/>
    94→			);
    95→		case "linear_scale":
    96→			return (
    97→				<LinearScaleQuestion
    98→					question={question}
    99→					value={value as number | undefined}
   100→					onChange={(v) => handleChange(v)}
   101→					error={error}
   102→				/>
   103→			);
   104→		case "date":
   105→			return (
   106→				<DateQuestion
   107→					question={question}
   108→					value={value as string | undefined}
   109→					onChange={(v) => handleChange(v)}
   110→					error={error}
   111→				/>
   112→			);
   113→		case "email":
   114→			return (
   115→				<EmailQuestion
   116→					question={question}
   117→					value={value as string | undefined}
   118→					onChange={(v) => handleChange(v)}
   119→					error={error}
   120→				/>
   121→			);
   122→		case "phone":
   123→			return (
   124→				<PhoneQuestion
   125→					question={question}
   126→					value={value as string | undefined}
   127→					onChange={(v) => handleChange(v)}
   128→					error={error}
   129→				/>
   130→			);
   131→		case "file_upload":
   132→			return (
   133→				<FileUploadQuestion
   134→					question={question}
   135→					value={value}
   136→					onChange={handleChange}
   137→					error={error}
   138→				/>
   139→			);
   140→		default:
   141→			return (
   142→				<div className="text-neutral-500">
   143→					Unknown question type: {question.type}
   144→				</div>
   145→			);
   146→	}
   147→}
