     5→type ThemeName = "light" | "dark";
     6→
     7→type AppThemeContextType = {
     8→	currentTheme: string;
     9→	isLight: boolean;
    10→	isDark: boolean;
    11→	setTheme: (theme: ThemeName) => void;
    12→	toggleTheme: () => void;
    13→};
