    42→	const value = useMemo(
    43→		() => ({
    44→			currentTheme: theme,
    45→			isLight,
    46→			isDark,
    47→			setTheme,
    48→			toggleTheme,
    49→		}),
    50→		[theme, isLight, isDark, setTheme, toggleTheme],
