     4→
     5→export function useMediaQuery(query: string) {
     6→	const [matches, setMatches] = React.useState(false);
     7→
     8→	React.useEffect(() => {
     9→		const media = window.matchMedia(query);
    10→		const listener = () => setMatches(media.matches);
    11→
    12→		// Set initial value
    13→		setMatches(media.matches);
    14→
    15→		media.addEventListener("change", listener);
    16→		return () => media.removeEventListener("change", listener);
    17→	}, [query]);
    18→
    19→	return matches;
    20→}
