     1→"use client";
     2→
     3→import {
     4→	type CollisionDetection,
     5→	closestCenter,
     6→	type DragEndEvent,
     7→	type DragOverEvent,
     8→	type DragStartEvent,
     9→	pointerWithin,
    10→} from "@dnd-kit/core";
    11→import { arrayMove } from "@dnd-kit/sortable";
    12→import type { Question, Survey } from "@orksys-survey/db";
    13→import { useState } from "react";
    14→import { toast } from "sonner";
    15→
    16→import { client } from "@/utils/orpc";
    17→import type { DragItem } from "../types";
    18→import { createMockQuestion, questionTypeLabels } from "../utils";
    19→
    20→export interface UseDragHandlersParams {
    21→	questions: Question[];
    22→	setQuestions: (
    23→		questions: Question[] | ((prev: Question[]) => Question[]),
    24→	) => void;
    25→	survey: Survey;
    26→	selectedQuestionId: string | null;
    27→	setSelectedQuestionId: (
    28→		id: string | null | ((prev: string | null) => string | null),
    29→	) => void;
    30→	reorderMutation: ReturnType<
    31→		typeof import("./use-question-mutations").useQuestionMutations
    32→	>["reorderMutation"];
    33→}
    34→
    35→export function useDragHandlers({
    36→	questions,
    37→	setQuestions,
    38→	survey,
    39→	selectedQuestionId,
    40→	setSelectedQuestionId,
    41→	reorderMutation,
    42→}: UseDragHandlersParams) {
    43→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
    44→	const [overId, setOverId] = useState<string | null>(null);
    45→
    46→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
    47→	const collisionDetection: CollisionDetection = (args) => {
    48→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
    49→		if (args.active.data.current?.questionType) {
    50→			const pointerCollisions = pointerWithin(args);
    51→			if (pointerCollisions.length > 0) {
    52→				return pointerCollisions;
    53→			}
    54→		}
    55→		// For canvas reordering, use closestCenter for better sortable behavior
    56→		return closestCenter(args);
    57→	};
    58→
    59→	const handleDragStart = (event: DragStartEvent) => {
    60→		const { active } = event;
    61→		const data = active.data.current;
    62→
    63→		if (data?.questionType) {
    64→			// Dragging from palette
    65→			setActiveDragItem({
    66→				type: "palette",
    67→				questionType: data.questionType as Question["type"],
    68→			});
    69→		} else {
    70→			// Dragging existing question
    71→			setActiveDragItem({
    72→				type: "question",
    73→				id: active.id as string,
    74→			});
    75→		}
    76→	};
    77→
    78→	const handleDragOver = (event: DragOverEvent) => {
    79→		const { over } = event;
    80→		setOverId(over?.id as string | null);
    81→	};
    82→
    83→	const handleDragEnd = (event: DragEndEvent) => {
    84→		const { active, over } = event;
    85→		setOverId(null);
    86→
    87→		if (!over) {
    88→			setActiveDragItem(null);
    89→			return;
    90→		}
    91→
    92→		// Handle cancel drop
    93→		if (over.id === "palette-cancel-zone") {
    94→			setActiveDragItem(null);
    95→			return;
    96→		}
    97→
    98→		// Handle palette drop (from question type palette) - use tracked drop index
    99→		if (active.data.current?.questionType) {
   100→			const questionType = active.data.current.questionType as Question["type"];
   101→
   102→			// Calculate insert index based on over.id
   103→			const overIndex = questions.findIndex((q) => q.id === over.id);
   104→			const insertIndex = overIndex === -1 ? questions.length : overIndex;
   105→
   106→			// Optimistic update
   107→			const tempId = `temp-${crypto.randomUUID()}`;
   108→			const mockQuestion = createMockQuestion(questionType);
   109→			const optimisticQuestion = { ...mockQuestion, id: tempId };
   110→
   111→			const optimisticQuestions = [
   112→				...questions.slice(0, insertIndex).map((q, i) => ({ ...q, order: i })),
   113→				{ ...optimisticQuestion, order: insertIndex },
   114→				...questions
   115→					.slice(insertIndex)
   116→					.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   117→			];
   118→
   119→			setQuestions(optimisticQuestions);
   120→			setSelectedQuestionId(tempId);
   121→
   122→			// Create question and reorder
   123→			client.question
   124→				.create({
   125→					surveyId: survey.id,
   126→					type: questionType,
   127→					title: `New ${questionTypeLabels[questionType] || questionType}`,
   128→					order: insertIndex,
   129→				})
   130→				.then((newQuestion) => {
   131→					// Replace optimistic question with real one
   132→					setQuestions((currentQuestions) => {
   133→						const updatedQuestions = currentQuestions.map((q) =>
   134→							q.id === tempId ? newQuestion : q,
   135→						);
   136→						return updatedQuestions;
   137→					});
   138→
   139→					setSelectedQuestionId((currentId) =>
   140→						currentId === tempId ? newQuestion.id : currentId,
   141→					);
   142→
   143→					// Invalidate queries
   144→					reorderMutation.mutate({
   145→						questions: [
   146→							...questions
   147→								.slice(0, insertIndex)
   148→								.map((q, i) => ({ ...q, order: i })),
   149→							{ ...newQuestion, order: insertIndex },
   150→							...questions
   151→								.slice(insertIndex)
   152→								.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   153→						].map((q) => ({
   154→							id: q.id,
   155→							order: q.order,
   156→						})),
   157→					});
   158→
   159→					toast.success("Question added");
   160→				})
   161→				.catch((error: Error) => {
   162→					// Revert on error
   163→					setQuestions(questions);
   164→					if (selectedQuestionId === tempId) setSelectedQuestionId(null);
   165→					toast.error(error.message || "Failed to create question");
   166→				});
   167→
   168→			setActiveDragItem(null);
   169→			return;
   170→		}
   171→
   172→		// Handle reordering
   173→		if (active.id !== over.id && over.id !== "canvas") {
   174→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   175→			const newIndex = questions.findIndex((q) => q.id === over.id);
   176→
   177→			if (oldIndex !== -1 && newIndex !== -1) {
   178→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   179→					(q, index) => {
   180→						// Only create new object if order actually changed
   181→						if (q.order === index) {
   182→							return q; // Preserve reference
   183→						}
   184→						return { ...q, order: index };
   185→					},
   186→				);
   187→
   188→				setQuestions(newQuestions);
   189→
   190→				reorderMutation.mutate({
   191→					questions: newQuestions.map((q) => ({
   192→						id: q.id,
   193→						order: q.order,
   194→					})),
   195→				});
   196→			}
   197→		}
   198→
   199→		setActiveDragItem(null); // Always called last
   200→	};
   201→
   202→	return {
   203→		activeDragItem,
   204→		overId,
   205→		collisionDetection,
   206→		handleDragStart,
   207→		handleDragOver,
   208→		handleDragEnd,
   209→	};
   210→}
