    10→export function useDebouncedSave(questionId: string) {
    11→	const queryClient = useQueryClient();
    12→	const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    13→
    14→	const updateMutation = useMutation(
    15→		orpc.question.update.mutationOptions({
    16→			onSuccess: () => {
    17→				queryClient.invalidateQueries({ queryKey: ["question"] });
    18→			},
    19→			onError: (error) => {
    20→				toast.error(error.message || "Failed to update question");
    21→			},
    22→		}),
    23→	);
    24→
    25→	const debouncedSave = (data: Partial<Question>) => {
    26→		if (saveTimeoutRef.current) {
    27→			clearTimeout(saveTimeoutRef.current);
    28→		}
    29→		// Convert null to undefined for API compatibility
    30→		const apiData = Object.fromEntries(
    31→			Object.entries(data).map(([key, value]) => [
    32→				key,
    33→				value === null ? undefined : value,
    34→			]),
    35→		);
    36→		saveTimeoutRef.current = setTimeout(() => {
    37→			updateMutation.mutate({
    38→				id: questionId,
    39→				data: apiData,
    40→			});
    41→		}, 1000);
    42→	};
    43→
    44→	return {
    45→		debouncedSave,
    46→		isPending: updateMutation.isPending,
    47→	};
    48→}
