   125→							) : table.getRowModel().rows?.length ? (
   126→								table.getRowModel().rows.map((row) => (
   127→									<TableRow key={row.id}>
   128→										{row.getVisibleCells().map((cell) => (
   129→											<TableCell key={cell.id}>
   130→												{flexRender(
   131→													cell.column.columnDef.cell,
   132→													cell.getContext(),
   133→												)}
   134→											</TableCell>
   135→										))}
   136→									</TableRow>
   137→								))
   138→							) : (
   139→								<TableRow>
   140→									<TableCell
   141→										colSpan={columns.length}
   142→										className="h-24 text-center"
   143→									>
   144→										No responses found.
   145→									</TableCell>
   146→								</TableRow>
   147→							)}
   148→						</TableBody>
   149→					</Table>
   150→				</div>
   151→
   152→				{responses.data?.pagination && (
   153→					<TablePagination
   154→						currentPage={page}
   155→						pageSize={20}
   156→						totalItems={responses.data.pagination.total}
   157→						totalPages={responses.data.pagination.totalPages}
   158→						onPreviousPage={() => setPage((p) => Math.max(1, p - 1))}
   159→						onNextPage={() => setPage((p) => p + 1)}
   160→					/>
   161→				)}
   162→			</CardContent>
   163→		</Card>
   164→	);
   165→}
