     1→"use client";
     2→
     3→import type * as React from "react";
     4→
     5→import { cn } from "@/lib/utils";
     6→
     7→interface NpsGaugeProps {
     8→	score: number;
     9→	className?: string;
    10→	showLabel?: boolean;
    11→	size?: "sm" | "md" | "lg";
    12→}
    13→
    14→const sizeConfig = {
    15→	sm: { radius: 40, strokeWidth: 8, fontSize: "text-2xl" },
    16→	md: { radius: 60, strokeWidth: 10, fontSize: "text-3xl" },
    17→	lg: { radius: 80, strokeWidth: 12, fontSize: "text-4xl" },
    18→};
    19→
    20→export function NpsGauge({
    21→	score,
    22→	className,
    23→	showLabel = true,
    24→	size = "md",
    25→}: NpsGaugeProps) {
    26→	const { radius, strokeWidth, fontSize } = sizeConfig[size];
    27→
    28→	// NPS ranges from -100 to 100
    29→	// Convert to 0-100 scale for display
    30→	const normalizedScore = Math.max(-100, Math.min(100, score));
    31→	const percentage = ((normalizedScore + 100) / 200) * 100;
    32→
    33→	// Determine color based on NPS score
    34→	const getColor = (nps: number) => {
    35→		if (nps >= 50) return "hsl(var(--chart-1))"; // Green - Excellent
    36→		if (nps >= 0) return "hsl(var(--chart-2))"; // Yellow - Good
    37→		return "hsl(var(--chart-5))"; // Red - Needs improvement
    38→	};
    39→
    40→	const getLabel = (nps: number) => {
    41→		if (nps >= 50) return "Excellent";
    42→		if (nps >= 0) return "Good";
    43→		return "Needs Work";
    44→	};
    45→
    46→	const color = getColor(normalizedScore);
    47→	const circumference = 2 * Math.PI * radius;
    48→	const strokeDashoffset = circumference - (percentage / 100) * circumference;
    49→
    50→	return (
    51→		<div className={cn("flex flex-col items-center gap-2", className)}>
    52→			<div className="relative">
    53→				<svg
    54→					width={radius * 2 + strokeWidth}
    55→					height={radius * 2 + strokeWidth}
    56→					className="-rotate-90 transform"
    57→				>
    58→					{/* Background circle */}
    59→					<circle
    60→						cx={radius + strokeWidth / 2}
    61→						cy={radius + strokeWidth / 2}
    62→						r={radius}
    63→						fill="none"
    64→						stroke="hsl(var(--muted))"
    65→						strokeWidth={strokeWidth}
    66→					/>
    67→					{/* Progress circle */}
    68→					<circle
    69→						cx={radius + strokeWidth / 2}
    70→						cy={radius + strokeWidth / 2}
    71→						r={radius}
    72→						fill="none"
    73→						stroke={color}
    74→						strokeWidth={strokeWidth}
    75→						strokeDasharray={circumference}
    76→						strokeDashoffset={strokeDashoffset}
    77→						strokeLinecap="round"
    78→						className="transition-all duration-500"
    79→					/>
    80→				</svg>
    81→				<div
    82→					className={cn(
    83→						"absolute inset-0 flex flex-col items-center justify-center",
