    17→
    18→interface BarChartProps {
    19→	data: Array<{
    20→		name: string;
    21→		value: number;
    22→		color?: string;
    23→	}>;
    24→	height?: number;
    25→	showGrid?: boolean;
    26→	showLabels?: boolean;
    27→	horizontal?: boolean;
    28→	className?: string;
    29→	formatter?: (value: number, name: string) => string;
    30→}
    31→
    32→export function BarChart({
    33→	data,
    34→	height = 300,
    35→	showGrid = true,
    36→	showLabels = true,
    37→	horizontal = false,
    38→	className,
    39→	formatter,
    40→}: BarChartProps) {
    41→	if (!data || data.length === 0) {
    42→		return <ChartEmpty />;
    43→	}
    44→
    45→	const maxBarSize = 60;
    46→
    47→	if (horizontal) {
    48→		return (
    49→			<div className={cn("w-full", className)} style={{ height }}>
    50→				<ResponsiveContainer width="100%" height="100%">
    51→					<RechartsBarChart
    52→						data={data}
    53→						layout="vertical"
    54→						margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
    55→					>
    56→						{showGrid && (
    57→							<CartesianGrid
    58→								strokeDasharray="3 3"
    59→								className="stroke-muted"
    60→								horizontal={false}
    61→							/>
    62→						)}
    63→						<XAxis
    64→							type="number"
    65→							tickLine={false}
    66→							axisLine={false}
    67→							tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }}
    68→						/>
    69→						<YAxis
    70→							dataKey="name"
    71→							type="category"
    72→							tickLine={false}
    73→							axisLine={false}
    74→							tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }}
    75→							width={100}
    76→							interval={0}
    77→						/>
    78→						<Tooltip content={<ChartTooltip formatter={formatter} />} />
    79→						<Bar dataKey="value" radius={[0, 4, 4, 0]} maxBarSize={maxBarSize}>
    80→							{data.map((entry, index) => (
    81→								<Cell
    82→									key={`cell-${index}`}
    83→									fill={
    84→										entry.color || CHART_COLORS[index % CHART_COLORS.length]
    85→									}
    86→								/>
    87→							))}
    88→						</Bar>
    89→					</RechartsBarChart>
    90→				</ResponsiveContainer>
    91→			</div>
    92→		);
    93→	}
    94→
    95→	return (
    96→		<div className={cn("w-full", className)} style={{ height }}>
    97→			<ResponsiveContainer width="100%" height="100%">
    98→				<RechartsBarChart
    99→					data={data}
   100→					margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
   101→				>
   102→					{showGrid && (
   103→						<CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
   104→					)}
   105→					<XAxis
   106→						dataKey="name"
   107→						tickLine={false}
   108→						axisLine={false}
   109→						tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }}
   110→						interval="preserveStartEnd"
   111→					/>
   112→					<YAxis
   113→						tickLine={false}
   114→						axisLine={false}
   115→						tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }}
   116→					/>
   117→					<Tooltip content={<ChartTooltip formatter={formatter} />} />
   118→					<Bar dataKey="value" radius={[4, 4, 0, 0]} maxBarSize={maxBarSize}>
   119→						{data.map((entry, index) => (
   120→							<Cell
   121→								key={`cell-${index}`}
   122→								fill={entry.color || CHART_COLORS[index % CHART_COLORS.length]}
   123→							/>
   124→						))}
   125→					</Bar>
   126→				</RechartsBarChart>
   127→			</ResponsiveContainer>
