     1→import type {
     2→	LogicRule,
     3→	Question,
     4→	Survey,
     5→	SurveySettings,
     6→} from "@orksys-survey/db";
     7→import { useMemo, useState } from "react";
     8→
     9→import type { AnswerValue } from "../context";
    10→import { useFingerprint } from "./use-fingerprint";
    11→import { useLogicEvaluator } from "./use-logic-evaluator";
    12→
    13→export interface UseRunnerStateOptions {
    14→	survey: Survey;
    15→	questions: Question[];
    16→	logicRules: LogicRule[];
    17→}
    18→
    19→export interface UseRunnerStateResult {
    20→	// Survey data
    21→	survey: Survey;
    22→	questions: Question[];
    23→	settings: SurveySettings | null;
    24→	logicRules: LogicRule[];
    25→	displayMode: "one_at_a_time" | "list";
    26→
    27→	// Response state
    28→	answers: Map<string, AnswerValue>;
    29→	currentQuestionIndex: number;
    30→	visibleQuestionIds: Set<string>;
    31→	visibleQuestions: Question[];
    32→	sortedQuestions: Question[];
    33→
    34→	// Navigation state
    35→	canGoBack: boolean;
    36→	canGoNext: boolean;
    37→	isComplete: boolean;
    38→
    39→	// Metadata
    40→	fingerprint: string | null;
    41→
    42→	// Setters
    43→	setAnswers: React.Dispatch<React.SetStateAction<Map<string, AnswerValue>>>;
    44→	setCurrentQuestionIndex: React.Dispatch<React.SetStateAction<number>>;
    45→	setIsComplete: React.Dispatch<React.SetStateAction<boolean>>;
    46→}
    47→
    48→/**
    49→ * Manages the state for the survey runner.
    50→ *
    51→ * This hook handles:
    52→ * - Sorting questions by order
    53→ * - Managing answer state
    54→ * - Evaluating logic rules to determine visibility
    55→ * - Computing navigation state (canGoBack, canGoNext)
    56→ */
    57→export function useRunnerState({
    58→	survey,
    59→	questions: allQuestions,
    60→	logicRules,
    61→}: UseRunnerStateOptions): UseRunnerStateResult {
    62→	const fingerprint = useFingerprint();
    63→	const [answers, setAnswers] = useState<Map<string, AnswerValue>>(new Map());
    64→	const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
    65→	const [isComplete, setIsComplete] = useState(false);
    66→
    67→	// Sort questions by order
    68→	const sortedQuestions = useMemo(
    69→		() => [...allQuestions].sort((a, b) => a.order - b.order),
    70→		[allQuestions],
    71→	);
    72→
    73→	// Evaluate logic to determine visibility
    74→	const { visibleQuestionIds } = useLogicEvaluator({
    75→		rules: logicRules,
    76→		answers,
    77→		questions: sortedQuestions,
    78→		currentQuestionId: sortedQuestions[currentQuestionIndex]?.id,
    79→	});
    80→
    81→	// Get visible questions
    82→	const visibleQuestions = useMemo(
    83→		() => sortedQuestions.filter((q) => visibleQuestionIds.has(q.id)),
    84→		[sortedQuestions, visibleQuestionIds],
    85→	);
    86→
    87→	// Get current visible question
    88→	const currentVisibleIndex = useMemo(() => {
    89→		const currentId = sortedQuestions[currentQuestionIndex]?.id;
    90→		if (!currentId) return 0;
    91→		return visibleQuestions.findIndex((q) => q.id === currentId);
    92→	}, [sortedQuestions, currentQuestionIndex, visibleQuestions]);
    93→
    94→	// Navigation state
    95→	const canGoBack = currentVisibleIndex > 0;
    96→	const canGoNext = currentVisibleIndex < visibleQuestions.length - 1;
    97→
    98→	const displayMode =
    99→		(survey.settings as SurveySettings | null)?.displayMode ?? "one_at_a_time";
   100→
   101→	return {
   102→		survey,
   103→		questions: sortedQuestions,
   104→		settings: survey.settings as SurveySettings | null,
   105→		logicRules,
   106→		displayMode,
   107→		answers,
   108→		currentQuestionIndex,
   109→		visibleQuestionIds,
   110→		visibleQuestions,
   111→		sortedQuestions,
   112→		canGoBack,
   113→		canGoNext,
   114→		isComplete,
   115→		fingerprint,
   116→		setAnswers,
   117→		setCurrentQuestionIndex,
   118→		setIsComplete,
   119→	};
   120→}
