     1→import type { Question, Survey, SurveySettings } from "@orksys-survey/db";
     2→import { useMutation } from "@tanstack/react-query";
     3→import { useRouter } from "next/navigation";
     4→import { useCallback, useMemo, useState } from "react";
     5→import { toast } from "sonner";
     6→
     7→import { client } from "@/utils/orpc";
     8→
     9→import type { AnswerValue } from "../context";
    10→import { validateAnswer } from "../utils/validation";
    11→
    12→export interface UseRunnerActionsOptions {
    13→	survey: Survey;
    14→	visibleQuestions: Question[];
    15→	sortedQuestions: Question[];
    16→	currentQuestionIndex: number;
    17→	answers: Map<string, AnswerValue>;
    18→	fingerprint: string | null;
    19→	setAnswers: React.Dispatch<React.SetStateAction<Map<string, AnswerValue>>>;
    20→	setCurrentQuestionIndex: React.Dispatch<React.SetStateAction<number>>;
    21→	setIsComplete: React.Dispatch<React.SetStateAction<boolean>>;
    22→	onComplete?: () => void;
    23→}
    24→
    25→export interface UseRunnerActionsResult {
    26→	// Actions
    27→	setAnswer: (questionId: string, value: AnswerValue) => void;
    28→	goNext: () => void;
    29→	goBack: () => void;
    30→	submit: () => Promise<void>;
    31→	validateAllQuestions: () => Map<string, string>;
    32→
    33→	// State
    34→	isSubmitting: boolean;
    35→	currentError: string | null;
    36→	clearError: () => void;
    37→}
    38→
    39→/**
    40→ * Provides navigation and submission actions for the survey runner.
    41→ *
    42→ * This hook handles:
    43→ * - Setting answers
    44→ * - Navigating between questions
    45→ * - Submitting the survey response
    46→ * - Validation
    47→ */
    48→export function useRunnerActions({
    49→	survey,
    50→	visibleQuestions,
    51→	sortedQuestions,
    52→	currentQuestionIndex,
    53→	answers,
    54→	fingerprint,
    55→	setAnswers,
    56→	setCurrentQuestionIndex,
    57→	setIsComplete,
    58→	onComplete,
    59→}: UseRunnerActionsOptions): UseRunnerActionsResult {
    60→	const router = useRouter();
    61→	const [currentError, setCurrentError] = useState<string | null>(null);
    62→
    63→	// Get current visible question
    64→	const currentVisibleIndex = useMemo(() => {
    65→		const currentId = sortedQuestions[currentQuestionIndex]?.id;
    66→		if (!currentId) return 0;
    67→		return visibleQuestions.findIndex((q) => q.id === currentId);
    68→	}, [sortedQuestions, currentQuestionIndex, visibleQuestions]);
    69→
    70→	const currentQuestion = visibleQuestions[currentVisibleIndex];
    71→
    72→	const canGoBack = currentVisibleIndex > 0;
    73→	const canGoNext = currentVisibleIndex < visibleQuestions.length - 1;
    74→
    75→	// Submit mutation
    76→	const submitMutation = useMutation({
    77→		mutationFn: async () => {
    78→			const answersArray = Array.from(answers.entries()).map(
    79→				([questionId, value]) => ({
    80→					questionId,
    81→					value,
    82→				}),
    83→			);
    84→
    85→			return client.response.submit({
    86→				surveyId: survey.id,
    87→				fingerprint: fingerprint ?? undefined,
    88→				answers: answersArray,
    89→				isComplete: true,
    90→				metadata: {
    91→					userAgent: navigator.userAgent,
    92→					language: navigator.language,
    93→					timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    94→				},
    95→			});
    96→		},
    97→		onSuccess: () => {
    98→			setIsComplete(true);
    99→			if (onComplete) {
   100→				onComplete();
   101→			} else {
   102→				// Navigate to complete page
   103→				const completeUrl = `/s/${survey.slug}/complete`;
   104→				const settings = survey.settings as SurveySettings | null;
   105→				if (settings?.thankYouMessage || settings?.redirectUrl) {
   106→					const params = new URLSearchParams();
   107→					if (settings.thankYouMessage) {
   108→						params.set("message", settings.thankYouMessage);
   109→					}
   110→					if (settings.redirectUrl) {
   111→						params.set("redirectUrl", settings.redirectUrl);
   112→					}
   113→					// eslint-disable-next-line @typescript-eslint/no-explicit-any
   114→					router.push(`${completeUrl}?${params.toString()}` as any);
   115→				} else {
   116→					// eslint-disable-next-line @typescript-eslint/no-explicit-any
   117→					router.push(completeUrl as any);
   118→				}
   119→			}
   120→		},
   121→		onError: (error) => {
   122→			toast.error(error.message || "Failed to submit response");
   123→		},
   124→	});
   125→
   126→	// Actions
   127→	const setAnswer = useCallback(
   128→		(questionId: string, value: AnswerValue) => {
   129→			setAnswers((prev: Map<string, AnswerValue>) => {
   130→				const next = new Map(prev);
   131→				next.set(questionId, value);
   132→				return next;
   133→			});
   134→			setCurrentError(null);
   135→		},
   136→		[setAnswers],
   137→	);
   138→
   139→	const goNext = useCallback(() => {
   140→		if (!currentQuestion) return;
   141→
   142→		// Validate current question
   143→		const answer = answers.get(currentQuestion.id);
   144→		const error = validateAnswer(currentQuestion, answer);
   145→		if (error) {
   146→			setCurrentError(error);
   147→			return;
   148→		}
   149→
   150→		if (canGoNext) {
   151→			const nextVisibleQuestion = visibleQuestions[currentVisibleIndex + 1];
   152→			if (nextVisibleQuestion) {
   153→				const nextIndex = sortedQuestions.findIndex(
   154→					(q) => q.id === nextVisibleQuestion.id,
   155→				);
   156→				setCurrentQuestionIndex(nextIndex);
   157→			}
   158→		}
   159→	}, [
   160→		currentQuestion,
   161→		answers,
   162→		canGoNext,
   163→		visibleQuestions,
   164→		currentVisibleIndex,
   165→		sortedQuestions,
   166→		setCurrentQuestionIndex,
   167→	]);
   168→
   169→	const goBack = useCallback(() => {
   170→		if (!canGoBack) return;
   171→
   172→		const prevVisibleQuestion = visibleQuestions[currentVisibleIndex - 1];
   173→		if (prevVisibleQuestion) {
   174→			const prevIndex = sortedQuestions.findIndex(
   175→				(q) => q.id === prevVisibleQuestion.id,
   176→			);
   177→			setCurrentQuestionIndex(prevIndex);
   178→		}
   179→	}, [
   180→		canGoBack,
   181→		visibleQuestions,
   182→		currentVisibleIndex,
   183→		sortedQuestions,
   184→		setCurrentQuestionIndex,
   185→	]);
   186→
   187→	const submit = useCallback(async () => {
   188→		if (!currentQuestion) return;
   189→
   190→		// Validate current question
   191→		const answer = answers.get(currentQuestion.id);
   192→		const error = validateAnswer(currentQuestion, answer);
   193→		if (error) {
   194→			setCurrentError(error);
   195→			return;
   196→		}
   197→
   198→		await submitMutation.mutateAsync();
   199→	}, [currentQuestion, answers, submitMutation]);
   200→
   201→	const clearError = useCallback(() => {
   202→		setCurrentError(null);
   203→	}, []);
   204→
   205→	const validateAllQuestions = useCallback(() => {
   206→		const errors = new Map<string, string>();
   207→		for (const question of visibleQuestions) {
   208→			const answer = answers.get(question.id);
   209→			const error = validateAnswer(question, answer);
   210→			if (error) {
   211→				errors.set(question.id, error);
   212→			}
   213→		}
   214→		return errors;
   215→	}, [visibleQuestions, answers]);
   216→
   217→	return {
   218→		setAnswer,
   219→		goNext,
   220→		goBack,
   221→		submit,
   222→		validateAllQuestions,
   223→		isSubmitting: submitMutation.isPending,
   224→		currentError,
   225→		clearError,
   226→	};
   227→}
