    25→
    26→const logicRuleSchema = z.object({
    27→	operator: z.enum([
    28→		"equals",
    29→		"not_equals",
    30→		"contains",
    31→		"greater_than",
    32→		"less_than",
    33→		"is_empty",
    34→		"is_not_empty",
    35→	]),
    36→	conditionValue: z.string(),
