    51→		orpc.logicRule.create.mutationOptions({
    52→			onSuccess: () => {
    53→				toast.success("Logic rule created");
    54→				onSuccess();
    55→			},
    56→			onError: (error) => {
    57→				toast.error(error.message || "Failed to create logic rule");
    58→			},
    59→		}),
    60→	);
    61→
    62→	const updateMutation = useMutation(
    63→		orpc.logicRule.update.mutationOptions({
    64→			onSuccess: () => {
    65→				toast.success("Logic rule updated");
    66→				onSuccess();
    67→			},
    68→			onError: (error) => {
    69→				toast.error(error.message || "Failed to update logic rule");
    70→			},
    71→		}),
    72→	);
    73→
    74→	const validateMutation = useQuery(
    75→		orpc.logicRule.validate.queryOptions({
    76→			input: { surveyId },
    77→			queryKey: ["logicRule", "validate", surveyId],
    78→		}),
    79→	);
    80→
    81→	const sourceQuestion = questions.find((q) => q.id === sourceQuestionId);
    82→
    83→	const form = useForm({
    84→		defaultValues: {
    85→			operator: (existingRule?.operator as string) || "equals",
    86→			conditionValue:
    87→				existingRule?.conditionValue !== null &&
    88→				existingRule?.conditionValue !== undefined
    89→					? String(existingRule.conditionValue)
    90→					: "",
    91→			action: (existingRule?.action as string) || "jump_to",
    92→			targetQuestionId: existingRule?.targetQuestionId || "",
    93→		},
    94→		onSubmit: async ({ value }) => {
    95→			const data = {
    96→				operator: value.operator as LogicRuleOperator,
    97→				action: value.action as LogicRuleAction,
    98→				conditionValue: needsConditionValue(value.operator)
    99→					? value.conditionValue
   100→					: undefined,
   101→				targetQuestionId: needsTargetQuestion(value.action)
   102→					? value.targetQuestionId
   103→					: undefined,
   104→			};
   105→
   106→			if (existingRule) {
   107→				await updateMutation.mutateAsync({
   108→					id: existingRule.id,
   109→					data,
   110→				});
   111→			} else {
   112→				await createMutation.mutateAsync({
   113→					surveyId,
   114→					sourceQuestionId,
   115→					...data,
   116→				});
   117→			}
   118→		},
   119→		validators: {
   120→			onSubmit: logicRuleSchema,
