     4→import { useForm } from "@tanstack/react-form";
     5→import { useMutation, useQuery } from "@tanstack/react-query";
     6→import { Loader2 } from "lucide-react";
     7→import { toast } from "sonner";
     8→import z from "zod";
     9→
    10→import { Button } from "@/components/ui/button";
    11→import { Label } from "@/components/ui/label";
    12→import { orpc } from "@/utils/orpc";
    13→import { needsConditionValue, needsTargetQuestion } from "./constants";
    14→import {
    15→	ActionSelect,
    16→	ConditionValueField,
    17→	OperatorSelect,
    18→	TargetQuestionSelect,
    19→} from "./form-fields";
    20→import type {
    21→	LogicRuleAction,
    22→	LogicRuleFormProps,
    23→	LogicRuleOperator,
    24→} from "./types";
    25→
    26→const logicRuleSchema = z.object({
    27→	operator: z.enum([
    28→		"equals",
    29→		"not_equals",
    30→		"contains",
    31→		"greater_than",
    32→		"less_than",
    33→		"is_empty",
    34→		"is_not_empty",
    35→	]),
    36→	conditionValue: z.string(),
    37→	action: z.enum(["jump_to", "skip", "show", "hide", "end_survey"]),
    38→	targetQuestionId: z.string(),
    39→});
    40→
    41→export function LogicRuleForm({
    42→	surveyId,
    43→	questions,
    44→	sourceQuestionId,
    45→	targetQuestions,
    46→	existingRule,
    47→	onSuccess,
    48→	onCancel,
    49→}: LogicRuleFormProps) {
    50→	const createMutation = useMutation(
    51→		orpc.logicRule.create.mutationOptions({
    52→			onSuccess: () => {
    53→				toast.success("Logic rule created");
    54→				onSuccess();
    55→			},
    56→			onError: (error) => {
    57→				toast.error(error.message || "Failed to create logic rule");
    58→			},
    59→		}),
    60→	);
    61→
    62→	const updateMutation = useMutation(
    63→		orpc.logicRule.update.mutationOptions({
    64→			onSuccess: () => {
    65→				toast.success("Logic rule updated");
    66→				onSuccess();
    67→			},
    68→			onError: (error) => {
    69→				toast.error(error.message || "Failed to update logic rule");
    70→			},
    71→		}),
    72→	);
    73→
    74→	const validateMutation = useQuery(
    75→		orpc.logicRule.validate.queryOptions({
    76→			input: { surveyId },
    77→			queryKey: ["logicRule", "validate", surveyId],
    78→		}),
    79→	);
    80→
    81→	const sourceQuestion = questions.find((q) => q.id === sourceQuestionId);
    82→
    83→	const form = useForm({
    84→		defaultValues: {
    85→			operator: (existingRule?.operator as string) || "equals",
    86→			conditionValue:
    87→				existingRule?.conditionValue !== null &&
    88→				existingRule?.conditionValue !== undefined
    89→					? String(existingRule.conditionValue)
    90→					: "",
    91→			action: (existingRule?.action as string) || "jump_to",
    92→			targetQuestionId: existingRule?.targetQuestionId || "",
    93→		},
    94→		onSubmit: async ({ value }) => {
    95→			const data = {
    96→				operator: value.operator as LogicRuleOperator,
    97→				action: value.action as LogicRuleAction,
    98→				conditionValue: needsConditionValue(value.operator)
    99→					? value.conditionValue
   100→					: undefined,
   101→				targetQuestionId: needsTargetQuestion(value.action)
   102→					? value.targetQuestionId
   103→					: undefined,
   104→			};
   105→
   106→			if (existingRule) {
   107→				await updateMutation.mutateAsync({
   108→					id: existingRule.id,
   109→					data,
   110→				});
   111→			} else {
   112→				await createMutation.mutateAsync({
   113→					surveyId,
   114→					sourceQuestionId,
   115→					...data,
   116→				});
   117→			}
   118→		},
   119→		validators: {
   120→			onSubmit: logicRuleSchema,
   121→		},
   122→	});
   123→
   124→	const isSubmitting = createMutation.isPending || updateMutation.isPending;
   125→
   126→	const sourceOptions = sourceQuestion?.config?.options || null;
   127→
   128→	return (
   129→		<form
   130→			onSubmit={(e) => {
   131→				e.preventDefault();
   132→				e.stopPropagation();
   133→				form.handleSubmit();
   134→			}}
   135→			className="space-y-4"
   136→		>
   137→			{/* Source Question Info */}
   138→			<div className="rounded-lg bg-neutral-50 p-3">
   139→				<Label className="text-neutral-500 text-xs uppercase tracking-wide">
   140→					Source Question
   141→				</Label>
   142→				<p className="mt-1 font-medium text-sm">{sourceQuestion?.title}</p>
   143→			</div>
   144→
   145→			{/* Operator Select */}
   146→			<form.Field name="operator">
   147→				{(field) => (
